def average(marks):
    return sum(marks) / len(marks)

def grade(avg):
    if avg >= 80:
        return "A+"
    elif avg >= 70:
        return "A"
    elif avg >= 60:
        return "A-"
    elif avg >= 40:
        return "C"
    return "F"

def report(name, marks):
    avg = average(marks)
    status = "Fail" if min(marks) < 40 else grade(avg)
    print(f"{name:<8} Total {sum(marks):>3}  Avg {avg:6.2f}  Result {status}")

report("Rahim", [78, 85, 62])
report("Sumaiya", [88, 76, 91])
report("Karim", [55, 35, 70])

def add(a, b):
    return a + b

def subtract(a, b):
    return a - b

def divide(a, b):
    if b == 0:
        return "Cannot divide by zero"
    return a / b

def menu():
    print("1. Add  2. Subtract  3. Divide  0. Exit")
    return input("Choose: ")

while True:
    choice = menu()
    if choice == "0":
        print("Goodbye!")
        break
    x = float(input("First number : "))
    y = float(input("Second number: "))
    if choice == "1":
        print("Result:", add(x, y))
    elif choice == "2":
        print("Result:", subtract(x, y))
    elif choice == "3":
        print("Result:", divide(x, y))

