def is_palindrome(text):
    clean = text.lower().replace(" ", "")
    return clean == clean[::-1]

for word in ["Madam", "level", "Python", "Never odd or even"]:
    if is_palindrome(word):
        print(word, "-> Palindrome")
    else:
        print(word, "-> Not palindrome")
